const x=$input.first().json;
const status=x._research_status||'failed';
const data=x.ai_data;

// DIRECT FIX: Hamesha pehle node se request_id uthayega
const reqId = $('Validate Request').first()?.json?.request_id || 'fallback-id';
const researchId = 'RES-' + reqId;

const evidence=[];
if(x.query_hash)evidence.push('query_hash='+x.query_hash);
evidence.push('ai_valid='+x.ai_valid+' sources_count='+(x._sources_count||0));

const limitations=['AI-assisted research based on model knowledge ONLY; live documentation retrieval NOT implemented.','Source references NOT verified to exist or be current.','AI pass does NOT prove runtime correctness.'];
if(!x.ai_valid&&x.ai_error)limitations.push('AI unavailable: '+x.ai_error);
if(x.source_url_provided)limitations.push('User source_url accepted as identifier only; NOT fetched.');
if(x.documentation_version)limitations.push('documentation_version NOT verified.');
if(x.ai_secret_redactions&&x.ai_secret_redactions.length>0)limitations.push(x.ai_secret_redactions.length+' field(s) in AI output were redacted due to secret-like patterns.');
if(data&&Array.isArray(data.caveats))limitations.push(...data.caveats);

let groqModel='openai/gpt-oss-120b',geminiModel='models/gemini-2.0-flash';
try{if($vars?.GROQ_MODEL)groqModel=$vars.GROQ_MODEL;}catch(e){}
try{if($vars?.GEMINI_MODEL)geminiModel=$vars.GEMINI_MODEL;}catch(e){}

const providerUsed=x.ai_valid?(x.ai_provider||'groq'):'none';
const modelUsed=providerUsed==='gemini'?geminiModel:(providerUsed==='groq'?groqModel:'none');

const verificationSummary={status:'not_verified',evidence,sources_verified:false,documentation_version_verified:false,provider:providerUsed,model:modelUsed};
const recommendedFixes=(x._all_issues||[]).map((iss,i)=>({finding_id:'V'+String(i+1).padStart(3,'0'),fix:'Address: '+iss.message}));

const result={
    audit_id:researchId,
    audit_status:status,
    cache_hit:false,
    question:x.question,
    answer:data?String(data.answer||'').slice(0,8000):'',
    findings:data?data.findings:[],
    source_references:data?data.source_references:[],
    sources_count:x._sources_count||0,
    documentation_version:data?data.documentation_version:null,
    confidence:x._effective_confidence||'unknown',
    confidence_original:data?data.confidence:'unknown',
    unresolved_questions:data?data.unresolved_questions:[],
    caveats:data?data.caveats:[],
    limitations,
    recommended_fixes:recommendedFixes,
    verification_summary:verificationSummary
};

const httpStatus=status==='failed'?500:200;
const errors=[];
if(!x.ai_valid&&x.ai_error)errors.push({category:x.ai_error_category||'MODEL_ERROR',message:'AI research unavailable: '+x.ai_error});

const warnings=status==='model_knowledge_only'?[{message:'No verifiable sources; model knowledge only'}]:[];
if(x.ai_secret_redactions&&x.ai_secret_redactions.length>0)warnings.push({message:x.ai_secret_redactions.length+' AI output field(s) redacted for secret-like patterns'});

return [{json:{
    request_id:reqId, 
    task_id:null, 
    status:status==='success'?'completed':(status==='model_knowledge_only'?'partial':'failed'), 
    _http_status:httpStatus, 
    result, 
    errors, 
    warnings, 
    verification:verificationSummary, 
    _persist:{
        project_id:x.project_id, 
        user_id:x.user_id, 
        claimed_user_id:x.user_id, 
        workspace_id:x.workspace_id, 
        conversation_id:x.conversation_id
    }
}}];

let src=null;try{if($('Build Result').isExecuted){const a=$('Build Result').first()?.json;if(a&&a.result)src=a;}}catch(e){}
if(!src){try{if($('Format Cache Hit Response').isExecuted){const b=$('Format Cache Hit Response').first()?.json;if(b&&b.result)src=b;}}catch(e){}}
if(!src){try{if($('Format Request Error').isExecuted){const c=$('Format Request Error').first()?.json;if(c&&c.result)src=c;}}catch(e){}}
if(!src){src={request_id:null,status:'failed',_http_status:500,result:{audit_id:null,audit_status:'failed',source_references:[]},verification:{status:'not_verified',evidence:[]},errors:[],task_id:null,warnings:[],_persist:{}};}
const cacheAttempted=(()=>{try{return $('Write Cache').isExecuted===true;}catch(e){return false;}})();
const cacheWritten=(()=>{try{if(!cacheAttempted)return false;const wc=$('Write Cache').first()?.json;if(wc&&(wc.id||wc.query_hash))return true;}catch(e){}return false;})();
const warnings=Array.isArray(src.warnings)?[...src.warnings]:[];
if(cacheAttempted&&!cacheWritten)warnings.push({message:'Cache write did not confirm; result not cached'});
return [{json:{...src,warnings,_cache_attempted:cacheAttempted,_cache_written:cacheWritten}}];

const src = $('Normalize Persist Source').first().json;
const sources = (src.result && src.result.source_references) || [];

// Robust Fallback for request_id
const reqId = $('Validate Request').first()?.json?.request_id || $('Webhook Input').first()?.json?.body?.request_id || src.request_id || 'fallback-req-id';
const auditId = 'RES-' + reqId;

if(sources.length === 0) {
    return [{json: {_empty: true, audit_id: auditId, request_id: reqId}}];
}

return sources.map((s,i) => ({
    json: {
        audit_id: auditId,
        finding_id: 'S' + String(i+1).padStart(3,'0'),
        severity: 'info',
        category: 'SOURCE_REFERENCE',
        node_id: null,
        node_name: null,
        description: String(s.title || '').slice(0,500) + ' | ' + String(s.url_or_identifier || '').slice(0,300) + ' [' + (s.source_type || 'unknown') + ']',
        evidence: null,
        suggested_fix: null,
        confidence: null,
        knowledge_status: 'Proposed',
        check_type: 'research_source'
    }
}));
